export default function About() {
  return (
    <section className="py-16 bg-white text-center px-6">
      <h2 className="text-4xl font-bold text-gray-900 mb-4">About Us</h2>
      <p className="text-lg text-gray-600 max-w-3xl mx-auto">
        We are a packaging company committed to providing sustainable and
        innovative solutions. Our mission is to deliver packaging that not only
        protects products but also enhances your brand.
      </p>
    </section>
  );
}
